const menuButton=document.querySelector('.menu-toggle'),nav=document.querySelector('.main-nav');
menuButton.addEventListener('click',()=>{const open=nav.classList.toggle('open');menuButton.setAttribute('aria-expanded',String(open));document.body.classList.toggle('menu-open',open)});
document.querySelectorAll('.nav-dropdown > button').forEach(button=>button.addEventListener('click',()=>{const dropdown=button.parentElement,open=dropdown.classList.toggle('open');button.setAttribute('aria-expanded',String(open))}));
nav.querySelectorAll('a').forEach(link=>link.addEventListener('click',()=>{nav.classList.remove('open');document.querySelectorAll('.nav-dropdown').forEach(item=>item.classList.remove('open'));menuButton.setAttribute('aria-expanded','false');document.body.classList.remove('menu-open')}));
const observer=new IntersectionObserver(entries=>entries.forEach(entry=>{if(entry.isIntersecting){entry.target.classList.add('visible');observer.unobserve(entry.target)}}),{threshold:.1});document.querySelectorAll('.reveal').forEach(element=>observer.observe(element));

