const staffGrid=document.querySelector('#staff-grid'),profileModal=document.querySelector('#profile-modal');
function renderStaff(){const location=document.querySelector('#filter-location').value,category=document.querySelector('#filter-category').value,experience=document.querySelector('#filter-experience').value,availability=document.querySelector('#filter-availability').value;const filtered=staff.filter(person=>(location==='all'||person.location===location)&&(category==='all'||person.category===category)&&(experience==='all'||person.experience>=Number(experience))&&(availability==='all'||person.availability===availability));staffGrid.innerHTML=filtered.map(person=>`<article class="profile-card"><img class="avatar" src="${person.image}" alt="Professional portrait of ${person.name}" loading="lazy"><div><span class="status">${person.availability} · Verified</span><h3>${person.name}</h3><p class="profile-meta">${person.category} · ${person.experience} years · ${person.location}</p><small>${person.skills.slice(0,2).join(' · ')}</small><div class="profile-actions"><button type="button" data-profile="${person.id}">View Profile</button><a href="#request" data-request="${person.category}">Request This Staff</a></div></div></article>`).join('');document.querySelector('.empty-state').hidden=filtered.length>0}
document.querySelectorAll('.staff-filters select').forEach(select=>select.addEventListener('change',renderStaff));renderStaff();
staffGrid.addEventListener('click',event=>{const profileButton=event.target.closest('[data-profile]'),requestLink=event.target.closest('[data-request]');if(profileButton){const person=staff.find(item=>item.id===Number(profileButton.dataset.profile));profileModal.querySelector('.modal-content').innerHTML=`<div class="profile-hero"><img src="${person.image}" alt="Professional portrait of ${person.name}"><div><p class="eyebrow">Verified candidate profile</p><h2>${person.name}</h2><p>${person.category} · ${person.experience} years’ experience · ${person.location}</p><p>${person.profile}</p><h3>Skills</h3><ul>${person.skills.map(skill=>`<li>${skill}</li>`).join('')}</ul><a class="button" href="#request" data-modal-request="${person.category}">Request This Staff</a></div></div>`;profileModal.showModal()}if(requestLink)selectRequestedCategory(requestLink.dataset.request)});
profileModal.addEventListener('click',event=>{const request=event.target.closest('[data-modal-request]');if(request){profileModal.close();selectRequestedCategory(request.dataset.modalRequest)}if(event.target===profileModal)profileModal.close()});profileModal.querySelector('.modal-close').addEventListener('click',()=>profileModal.close());function selectRequestedCategory(category){document.querySelector('#request-form [name="category"]').value=category}

const categories=[['Housekeepers','Consistent care for clean, comfortable and organised homes.','housekeeper'],['Cooks','Everyday meals prepared around your family’s tastes and routine.','cook'],['Nannies','Attentive, age-appropriate support for children and parents.','nanny'],['Caregivers','Respectful companionship and practical support for loved ones.','caregiver'],['Drivers','Safe and punctual transport for family and household needs.','driver'],['Cleaners','Flexible cleaning help for regular or occasional requirements.','cleaner'],['Laundry Staff','Washing, ironing, fabric care and wardrobe organisation.','laundry'],['Personal Assistants','Dependable organisation for household and personal tasks.','assistant']];document.querySelector('#category-grid').innerHTML=categories.map(([name,description,image])=>`<article class="category-card ${image}"><div><h3>${name}</h3><p>${description}</p><a href="#staff">View Available Staff →</a></div></article>`).join('');
document.querySelector('#quick-search').addEventListener('submit',event=>{event.preventDefault();document.querySelector('#staff').scrollIntoView({behavior:'smooth'})});
function handleForm(form,message){form.addEventListener('submit',event=>{event.preventDefault();form.querySelector('.form-success').textContent=message;form.reset()})}handleForm(document.querySelector('#request-form'),'Thank you. Our team will contact you shortly regarding your staff request.');handleForm(document.querySelector('#consultation-form'),'Thank you. Your consultation request has been received and our team will contact you to confirm.');handleForm(document.querySelector('#contact-form'),'Thank you. Your message has been received and our team will respond shortly.');
let slide=0;const quotes=document.querySelector('.testimonial-slider .quotes');document.querySelectorAll('.slider-button').forEach(button=>button.addEventListener('click',()=>{slide=(slide+(button.classList.contains('next')?1:-1)+3)%3;quotes.style.transform=`translateX(-${slide*100}%)`}));
const legalCopy={privacy:`<p class="eyebrow">Legal</p><h2>Privacy Policy</h2><p>Last updated: October 5, 2026</p><h3>Information we collect</h3><p>We collect details you provide through enquiries, consultation bookings and staff requests, including contact details, location, staffing requirements and preferred schedules.</p><h3>How we use information</h3><p>Information is used to respond to enquiries, arrange consultations, identify potential matches, coordinate recruitment and improve our service. We do not sell personal information.</p><h3>Protection and retention</h3><p>We use reasonable administrative and technical measures to protect submitted information and retain it only as long as needed for service, legal and operational purposes.</p><h3>Your choices</h3><p>You may request access, correction or deletion of your information, subject to legal obligations. Email <a href="mailto:handsandhomes27@gmail.com">handsandhomes27@gmail.com</a>.</p>`,terms:`<p class="eyebrow">Legal</p><h2>Terms & Conditions</h2><p>Last updated: October 5, 2026</p><h3>Website and recruitment services</h3><p>Hands & Homes provides recruitment support and introductions. Availability, timelines and suitability depend on the role and information supplied.</p><h3>Client responsibilities</h3><p>Clients are responsible for accurate requirements, final interviews and selection, lawful and fair working conditions, compensation, supervision and compliance with applicable employment obligations.</p><h3>Matching and verification</h3><p>Screening reduces risk but cannot guarantee future conduct or performance. Clients should make their own final hiring assessment.</p><h3>Payments, cancellations and replacements</h3><p>Applicable fees, due dates, cancellation terms and replacement assistance will be stated in the service agreement before work begins.</p><h3>Limitations</h3><p>Hands & Homes is not responsible for indirect losses or circumstances outside reasonable control. These terms do not exclude rights that cannot lawfully be excluded.</p>`};
const legalModal=document.querySelector('#legal-modal');document.querySelectorAll('[data-modal]').forEach(link=>link.addEventListener('click',event=>{event.preventDefault();legalModal.querySelector('.modal-content').innerHTML=legalCopy[link.dataset.modal];legalModal.showModal()}));legalModal.querySelector('.modal-close').addEventListener('click',()=>legalModal.close());legalModal.addEventListener('click',event=>{if(event.target===legalModal)legalModal.close()});
